ratio": 1.0312, "active_tension_exposure_sum_cm2": 42.37}	{"wrist_flexors": 0.9500, "wrist_extensors": 1.0000, "pronators_supinators": 0.9500}	{"slug": "seated_dumbbell_wrist_extension", "notes": ["No exercise-specific mechanism of persistent recovery cost is present: the movement is a short-range, low-absolute-force, controlled dynamic isolation with a conventional eccentric and full inter-repetition unloading.", "The high tension fraction of the wrist extensors was deliberately not converted into a modifier, since that magnitude is already represented in Active Tension Exposure and no structural mechanism accompanies it.", "The forearm being braced against a bench or thigh removes stabilization and force-reversal demands rather than adding recovery cost.", "Acute burning and pump commonly reported in direct forearm work were explicitly excluded, as that fatigue resolves quickly and is not the target variable."], "reconciliation": "PASS", "muscle_evaluation": [{"R_m": 1.0000, "muscle": "wrist_extensors", "rationale": "Conventional dynamic wrist extension over a short range with a controlled eccentric into flexion. Although the forearm is braced and the muscle does lengthen at the bottom, the absolute force involved is small relative to the group's structural tolerance and the range is limited, so the lengthened-position component is mild and does not constitute the high-force active lengthening that would justify elevation. The high tension fraction reflects load magnitude already carried by T_m, and the brief tension duration offsets it; the neutral reference is the appropriate estimate.", "maximum_fcsa_cm2": 53.67, "tension_fraction": 0.7149, "perfusion_constraint": "low", "force_development_profile": "controlled", "relative_tension_severity": "high", "active_tension_exposure_cm2": 38.37, "eccentric_structural_stress": "standard", "meaningful_tension_duration": "brief", "sustained_isometric_tension": "none", "dominant_recovery_mechanisms": ["conventional_contractile_fatigue"], "high_force_lengthening_at_long_length": "mild"}, {"R_m": 0.9500, "muscle": "wrist_flexors", "rationale": "Contributes only light isometric grip tension to retain the dumbbell; the force is submaximal, non-lengthening and released between repetitions, so its fatigue is largely transient and its persistent cost per unit tension falls slightly below the dynamic reference.", "maximum_fcsa_cm2": 54.40, "tension_fraction": 0.0551, "perfusion_constraint": "low", "force_development_profile": "controlled", "relative_tension_severity": "low", "active_tension_exposure_cm2": 3.00, "eccentric_structural_stress": "minimal", "meaningful_tension_duration": "brief", "sustained_isometric_tension": "intermittent", "dominant_recovery_mechanisms": ["low_level_gripping_isometric_tension"], "high_force_lengthening_at_long_length": "none"}, {"R_m": 0.9500, "muscle": "pronators_supinators", "rationale": "Holds forearm rotation fixed at very low force against a supported thigh or bench; no dynamic excursion and no loaded lengthening occur, leaving minimal persistent local deficit and placing it just below reference.", "maximum_fcsa_cm2": 60.88, "tension_fraction": 0.0164, "perfusion_constraint": "low", "force_development_profile": "controlled", "relative_tension_severity": "low", "active_tension_exposure_cm2": 1.00, "eccentric_structural_stress": "minimal", "meaningful_tension_duration": "brief", "sustained_isometric_tension": "intermittent", "dominant_recovery_mechanisms": ["low_level_stabilizing_isometric_tension"], "high_force_lengthening_at_long_length": "none"}], "modifier_distribution": {"mode": 0.9500, "median": 0.9500, "maximum": 1.0000, "minimum": 0.9500, "unweighted_mean": 0.9667, "tension_weighted_mean": 0.9965}, "standardized_repetition": {"tempo": "controlled conventional tempo", "range_of_motion": "full intended ROM", "proximity_to_failure": "effective repetition"}, "active_tension_exposure_sum_cm2": 42.37}	{"elbow_joint": 0.0800, "radiocarpal_joint": 0.7600}	{"slug": "seated_dumbbell_wrist_extension", "notes": ["This is a highly localized wrist-extension exercise, with the supported forearm minimizing proximal-joint loading.", "The radiocarpal score is high relative to conventional wrist-loading exercises because resistance acts directly through a substantial hand moment arm while the wrist extensors generate large local force."], "loaded_joints": ["radiocarpal_joint", "elbow_joint"], "reconciliation": "PASS", "joint_evaluation": [{"joint": "radiocarpal_joint", "rationale": "The radiocarpal joint is the primary loaded articulation. With the forearms supported and the dumbbells acting through the hand, the external resistance produces a direct wrist-flexion moment that must be opposed by the wrist extensors. High extensor force relative to their short internal moment arms produces substantial joint reaction and compression. Full intended ROM places meaningful load into wrist flexion and extension, making joint position mechanically relevant. Independent dumbbells add some stabilization demand, although the supported forearm substantially constrains the movement.", "load_exposure": 0.7600, "loaded_joint_position": "demanding", "primary_loading_modes": ["net_joint_moment", "compression", "muscle_force_transmission", "loaded_end_range"], "net_joint_moment_demand": "high", "stabilization_requirement": "moderate", "shear_translation_or_rotation": "low", "muscle_force_and_joint_reaction": "high"}, {"joint": "elbow_joint", "rationale": "The elbow is largely fixed while the forearm is externally supported, so little elbow moment or stabilization is required. Some force generated by forearm muscles and transmitted through their proximal attachments produces minor mechanical exposure, but the elbow is not a meaningful load-bearing target of the exercise.", "load_exposure": 0.0800, "loaded_joint_position": "favorable", "primary_loading_modes": ["muscle_force_transmission"], "net_joint_moment_demand": "minimal", "stabilization_requirement": "minimal", "shear_translation_or_rotation": "minimal", "muscle_force_and_joint_reaction": "low"}], "maximum_exposure_joint": "radiocarpal_joint", "standardized_repetition": {"tempo": "controlled conventional tempo", "range_of_motion": "full intended ROM", "proximity_to_failure": "effective repetition"}}
